<script setup lang="ts">import{onMounted,ref,computed}from'vue';import{ElMessage}from'element-plus';import{request,userId}from'../../api/client';import DramaCard from'../../components/DramaCard.vue';const loading=ref(false),search=ref(''),dramas=ref<any[]>([]);const demo=[{drama_id:101,title:'The Contract Wife',country:'US',language:'en',is_paid:true,price_cents:499,reasons:['Trending','CEO Romance']},{drama_id:102,title:'Revenge of the Hidden Heiress',country:'US',language:'en',is_paid:true,price_cents:699,reasons:['Revenge','Billionaire']},{drama_id:103,title:'CEO Next Door',country:'GB',language:'en',is_paid:false,reasons:['Free','Romance']},{drama_id:104,title:'After the Last Goodbye',country:'US',language:'en',is_paid:false,reasons:['New Release','Emotional']}];const list=computed(()=> (dramas.value.length?dramas.value:demo).filter(x=>!search.value||x.title.toLowerCase().includes(search.value.toLowerCase())));async function load(){loading.value=true;try{const j=await request('/api/v1/feed?user_id='+userId()+'&country=US&language=en&page_size=20');dramas.value=j.items||[]}catch{ElMessage.warning('API 未启动，当前显示演示数据')}finally{loading.value=false}}onMounted(load)</script>
<template><section><div class="hero"><div><p class="eyebrow">GLOBAL SHORT DRAMA · 2026</p><h1>Tonight's story starts here.</h1><p>Fast, emotional short dramas built for global viewing.</p></div><el-button type="primary" size="large" @click="$router.push('/discover')">Explore now →</el-button></div><div class="section-head"><div><p class="eyebrow">PERSONAL PICKS</p><h2>For You</h2></div><el-button text :loading="loading" @click="load">Refresh</el-button></div><div class="toolbar"><el-input v-model="search" placeholder="Search dramas..." clearable/><div class="chips"><el-tag>All</el-tag><el-tag>Romance</el-tag><el-tag>Revenge</el-tag><el-tag>CEO</el-tag></div></div><div class="grid"><DramaCard v-for="x in list" :key="x.drama_id" :drama="x"/></div></section></template>